  [492, 82], [548, 34], [604, 108], [672, 46], [726, 92], [838, 30], [912, 72],
  [1018, 22], [1072, 148], [1180, 52], [1234, 116], [1290, 44], [1348, 92],
  [1408, 28], [1468, 78], [78, 190], [204, 178], [520, 190], [962, 196], [1272, 204],
