  /** Call from a pointer or key handler: browsers need a gesture before sound may start. */
  function unlock() {
    ensure();
    if (context && context.state === 'suspended') {
      context.resume().catch(() => {});
    }
  }

  function setMuted(value) {
    muted = value;
  }

  return { play, unlock, setMuted };
